use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/direct-ref-pack";
fn main(){let mut all=BTreeMap::new();for label in["frozen","fresh","selected"]{
    let bin=format!("{R}/{label}-probe");let nm=Command::new("nm").args(["-S","--defined-only",&bin]).output().unwrap();assert!(nm.status.success());fs::write(format!("{R}/{label}-nm.log"),&nm.stdout).unwrap();let text=String::from_utf8(nm.stdout).unwrap();let mut rows=vec![];
    for line in text.lines(){let v:Vec<_>=line.split_whitespace().collect();if v.len()!=4{continue}let name=format!("{:#}",rustc_demangle::demangle(v[3]));if !name.contains("stream_g1_impl"){continue}let dis=Command::new("objdump").args(["-d","-w","--insn-width=16",&format!("--disassemble={}",v[3]),&bin]).output().unwrap();assert!(dis.status.success());let t=String::from_utf8(dis.stdout).unwrap();let file=format!("{R}/{label}-g1-stream-{}.log",rows.len());fs::write(&file,&t).unwrap();let(mut ins,mut ifma,mut stack,mut inserts,mut memory_inserts)=(0u64,0u64,0u64,0u64,0u64);for l in t.lines(){let f:Vec<_>=l.split('\t').collect();if f.len()<3{continue}let a=f[2].trim();ins+=1;if a.starts_with("vpmadd52"){ifma+=1}if a.contains("(%rsp")||a.contains("(%rbp"){stack+=1}if a.starts_with("vinserti64x4"){inserts+=1;if a.contains('('){memory_inserts+=1}}}rows.push(json!({"symbol":name,"raw_symbol":v[3],"address":v[0],"text_bytes":u64::from_str_radix(v[1],16).unwrap(),"instructions":ins,"IFMA_sites":ifma,"stack_address_operand_sites":stack,"vinserti64x4_sites":inserts,"vinserti64x4_memory_operand_sites":memory_inserts,"disassembly":file}));}
    assert!(!rows.is_empty());all.insert(label,json!({"binary_sha256":format!("{:x}",Sha256::digest(fs::read(bin).unwrap())),"G1_stream_symbols":rows}));
}fs::write(format!("{R}/codegen-audit.json"),serde_json::to_vec_pretty(&json!({"variants":all,"scope":"actual linked caller G1 streaming functions; whole function static counts, not dynamic instructions/copies/spills or proof walltime","new_input_semantics":"loads32bytes from each reference, no contiguous coordinate-array API; instruction lowering may fold loads into inserts"})).unwrap()).unwrap();println!("SavedactualcallerG1disassembly/staticcountsforall3variants");}
